    country = ws.cell(r, 3).value
    rows.append((r, customer, amount, country))

# For each customer, find the non-US country with the highest amount
customer_max = {}
for r, customer, amount, country in rows:
    if country != 'US':
        if customer not in customer_max:
            customer_max[customer] = (amount, country)
        else:
            if amount > customer_max[customer][0]:
                customer_max[customer] = (amount, country)

